def stream_range(text: str, size: int):
    """range 版:由语言推进并检查终止。"""
    if size <= 0:
        raise ValueError('size 必须为正')
    for i in range(0, len(text), size):
        yield text[i:i + size]

def stream_while(text: str, size: int):
    """while 版:自己推进索引——同样正确,但终止要自己维护。"""
    if size <= 0:
        raise ValueError('size 必须为正')
    i = 0
    while i < len(text):
        yield text[i:i + size]
        i += size            # 忘记这行 → 死循环

for c in stream_range('流式输出的本质是生成器', 4):
    print(c, end='|')
print()
for c in stream_while('流式输出的本质是生成器', 4):
    print(c, end='|')
print()
try:
    list(stream_range('abc', 0))   # size=0:快速失败
except ValueError as e:
    print('size=0 →', e)

