import json

TOOLS = {
    'get_weather': lambda city: {'city': city, 'weather': '晴 25°C', 'source': '示意数据'},
}

def model_turn(messages):
    """替身模型:按对话历史决定『调用工具』还是『给最终回答』。
    真实场景这一步是 LLM;这里用规则模拟,专注循环本身。
    结果协议:工具返回 {'error': ...} 视为失败——失败要如实说明或换路,不冒充成功。"""
    user_msg = [m for m in messages if m['role'] == 'user'][-1]['content']
    tool_msgs = [m for m in messages if m['role'] == 'tool']
    if '天气' in user_msg and not tool_msgs:
        return {'type': 'tool_call', 'name': 'get_weather', 'args': {'city': '北京'}}
    if tool_msgs:
        last = json.loads(tool_msgs[-1]['content'])
        if 'error' in last:   # 工具失败:如实告知失败与原因,不给成功建议
            return {'type': 'final', 'answer': '查询失败(' + last['error'] + '),没能拿到天气数据。'}
        return {'type': 'final', 'answer': '根据工具结果(' + json.dumps(last, ensure_ascii=False) + '),今天适合出行。'}
    return {'type': 'final', 'answer': '这个问题不需要工具,我直接回答。'}

def run_agent(user_input, max_rounds=3):
    """完整循环:用户输入 → 模型意图 → 应用执行工具 → 结果回传 → 模型终答。"""
    messages = [{'role': 'user', 'content': user_input}]
    model_calls = 0
    for _ in range(max_rounds):
        model_calls += 1
        decision = model_turn(messages)
        if decision['type'] == 'final':
            return decision['answer'], model_calls
        name, args = decision['name'], decision['args']
        try:
            tool = TOOLS.get(name)
            if tool is None:
                result = {'error': '未知工具 ' + name}   # 回喂错误,让模型换路
            else:
                result = tool(**args)
        except Exception as e:
            result = {'error': '工具执行失败: ' + str(e)}   # 工具异常 ≠ 最终答案
        messages.append({'role': 'assistant', 'content': json.dumps(decision, ensure_ascii=False)})
        messages.append({'role': 'tool', 'content': json.dumps(result, ensure_ascii=False)})
    return '达到最大轮次,已终止(护栏防死循环)', model_calls

ans, calls = run_agent('北京天气怎么样?')
print(ans, '| 模型调用', calls, '次')
ans2, calls2 = run_agent('1+1等于几?')
print(ans2, '| 模型调用', calls2, '次')
